1	package govflow
2	
3	import (
4		"errors"
5		"fmt"
6		"sort"
7	)
8	
9	// 投票提案相关错误。
10	var (
11		// ErrInvalidProposal：创建投票提案的参数非法（编号/成员/权重/时间/委托等）。
12		ErrInvalidProposal = errors.New("invalid voting proposal")
13		// ErrProposalNotFound 见 store.go。
14		// ErrProposalConflict：同编号提案已存在但内容或来源不同，或重复投票选择不同。
15		// ErrVoteRejected：投票被拒绝（时间窗口外、投票人无资格等）。
16		ErrVoteRejected = errors.New("vote rejected")
17		// ErrTallyRejected：计票被拒绝（截止时刻未到）。
18		ErrTallyRejected = errors.New("tally rejected")
19	)
20	
21	// ---- 输入与对外视图 ----
22	
23	// VoteMember 是创建投票提案时提交的一名成员及其原始权重。
24	type VoteMember struct {
25		ID     string `json:"id"`
26		Weight int64  `json:"weight"`
27	}
28	
29	// Delegation 表示 From 把投票权委托给 To。委托可以继续转交，
30	// 最终未再委托的人代表沿途所有成员投票。
31	type Delegation struct {
32		From string `json:"from"`
33		To   string `json:"to"`
34	}
35	
36	// CreateVoteInput 是创建一项投票提案的完整输入。
37	type CreateVoteInput struct {
38		ID          string
39		Members     []VoteMember
40		Delegations []Delegation
41		Quorum      int64
42		StartAt     int64
43		Deadline    int64
44		TimelockEnd int64
45		Actions     []string
46	}
47	
48	// MemberView 是查询时展示的一名成员：委托路径、最终代表与原始权重。
49	type MemberView struct {
50		ID       string   `json:"id"`
51		Weight   int64    `json:"weight"`
52		Path     []string `json:"path"`      // 从本人到最终代表的完整编号链（含首尾）
53		Delegate string   `json:"delegate"`  // 最终代表
54		Direct   string   `json:"direct_to"` // 直接委托对象；未委托为空串
55	}
56	
57	// BallotView 是查询时展示的一张已投出的票。
58	type BallotView struct {
59		Representative string `json:"representative"`
60		Weight         int64  `json:"weight"`
61		Support        bool   `json:"support"`
62		VotedAt        int64  `json:"voted_at"`
63	}
64	
65	// TallyResultView 是首次计票结论的查询视图；尚未计票时为 nil。
66	type TallyResultView struct {
67		ForWeight     int64 `json:"for_weight"`
68		AgainstWeight int64 `json:"against_weight"`
69		Turnout       int64 `json:"turnout"`
70		Quorum        int64 `json:"quorum"`
71		Passed        bool  `json:"passed"`
72		TalliedAt     int64 `json:"tallied_at"`
73	}
74	
75	// VoteProposalView 是一项投票提案的完整对外视图。
76	type VoteProposalView struct {
77		ID          string           `json:"id"`
78		Source      string           `json:"source"` // vote
79		State       string           `json:"state"`  // voting / passed / rejected / executed
80		Quorum      int64            `json:"quorum"`
81		StartAt     int64            `json:"start_at"`
82		Deadline    int64            `json:"deadline"`
83		TimelockEnd int64            `json:"timelock_end"`
84		Actions     []string         `json:"actions"`
85		TotalWeight int64            `json:"total_weight"`
86		Members     []MemberView     `json:"members"`
87		Ballots     []BallotView     `json:"ballots"`
88		Tally       *TallyResultView `json:"tally,omitempty"`
89	}
90	
91	// ---- 磁盘结构（JSON，版本仍为 1） ----
92	
93	type storedMember struct {
94		ID     string `json:"id"`
95		Weight int64  `json:"weight"`
96	}
97	
98	type storedDelegation struct {
99		From string `json:"from"`
100		To   string `json:"to"`
101	}
102	
103	type storedBallot struct {
104		Representative string `json:"representative"`
105		Weight         int64  `json:"weight"`
106		Support        bool   `json:"support"`
107		VotedAt        int64  `json:"voted_at"`
108	}
109	
110	type storedTally struct {
111		ForWeight     int64 `json:"for_weight"`
112		AgainstWeight int64 `json:"against_weight"`
113		TalliedAt     int64 `json:"tallied_at"`
114	}
115	
116	// storedVoteProposal 按成员提交顺序保存成员与委托（顺序不影响相等性），
117	// 动作文本与顺序原样保存（顺序影响相等性）。
118	type storedVoteProposal struct {
119		ID          string             `json:"id"`
120		State       string             `json:"state"`
121		Members     []storedMember     `json:"members"`
122		Delegations []storedDelegation `json:"delegations"`
123		Quorum      int64              `json:"quorum"`
124		StartAt     int64              `json:"start_at"`
125		Deadline    int64              `json:"deadline"`
126		TimelockEnd int64              `json:"timelock_end"`
127		Actions     []string           `json:"actions"`
128		Ballots     []storedBallot     `json:"ballots"`
129		Tally       *storedTally       `json:"tally,omitempty"`
130	}
131	
132	// ---- 校验与派生 ----
133	
134	type proposalSpec struct {
135		members  []VoteMember
136		weights  map[string]int64
137		delegate map[string]string // 直接委托对象
138		pathOf   map[string][]string
139		headOf   map[string]string // 最终代表
140		groupW   map[string]int64  // 最终代表名下归集的全部原始权重
141		total    int64
142	}
143	
144	// validateProposalInput 校验全部创建规则并派生委托路径与代表权重。
145	// 任何非法条件都返回错误，调用方必须整项拒绝。
146	func validateProposalInput(in *CreateVoteInput) (*proposalSpec, error) {
147		if in.ID == "" {
148			return nil, invalidProposal("proposal id must not be empty")
149		}
150		if len(in.Members) == 0 {
151			return nil, invalidProposal("proposal %s: member list must not be empty", in.ID)
152		}
153		weights := make(map[string]int64, len(in.Members))
154		order := make([]string, 0, len(in.Members))
155		for _, m := range in.Members {
156			if m.ID == "" {
157				return nil, invalidProposal("proposal %s: member id must not be empty", in.ID)
158			}
159			if _, dup := weights[m.ID]; dup {
160				return nil, invalidProposal("proposal %s: duplicate member %q", in.ID, m.ID)
161			}
162			if m.Weight <= 0 {
163				return nil, invalidProposal("proposal %s: member %q weight must be a positive integer, got %d", in.ID, m.ID, m.Weight)
164			}
165			weights[m.ID] = m.Weight
166			order = append(order, m.ID)
167		}
168	
169		// 总权重必须在 int64 范围内（各权重已为正）。
170		var total int64
171		for _, m := range in.Members {
172			sum, ok := addInt64(total, m.Weight)
173			if !ok {
174				return nil, invalidProposal("proposal %s: total member weight overflows int64", in.ID)
175			}
176			total = sum
177		}
178	
179		if in.Quorum < 1 || in.Quorum > total {
180			return nil, invalidProposal("proposal %s: quorum must be between 1 and total weight %d, got %d", in.ID, total, in.Quorum)
181		}
182		if !(0 <= in.StartAt && in.StartAt < in.Deadline && in.Deadline <= in.TimelockEnd) {
183			return nil, invalidProposal("proposal %s: times must satisfy 0 <= start < deadline <= timelock, got start=%d deadline=%d timelock=%d",
184				in.ID, in.StartAt, in.Deadline, in.TimelockEnd)
185		}
186	
187		delegate := make(map[string]string, len(in.Delegations))
188		for _, d := range in.Delegations {
189			if d.From == "" || d.To == "" {
190				return nil, invalidProposal("proposal %s: delegation members must not be empty", in.ID)
191			}
192			if _, ok := weights[d.From]; !ok {
193				return nil, invalidProposal("proposal %s: delegation from unknown member %q", in.ID, d.From)
194			}
195			if _, ok := weights[d.To]; !ok {
196				return nil, invalidProposal("proposal %s: delegation to unknown member %q", in.ID, d.To)
197			}
198			if d.From == d.To {
199				return nil, invalidProposal("proposal %s: member %q must not delegate to itself", in.ID, d.From)
200			}
201			if _, dup := delegate[d.From]; dup {
202				return nil, invalidProposal("proposal %s: member %q delegates more than once", in.ID, d.From)
203			}
204			delegate[d.From] = d.To
205		}
206	
207		// 解析每条委托链：自委托已拦，这里检测循环并得到最终代表。
208		pathOf := make(map[string][]string, len(weights))
209		headOf := make(map[string]string, len(weights))
210		for _, id := range order {
211			if _, done := headOf[id]; done {
212				continue
213			}
214			chain := []string{id}
215			onChain := map[string]int{id: 0}
216			cur := id
217			for {
218				next, has := delegate[cur]
219				if !has {
220					break
221				}
222				if pos, cyc := onChain[next]; cyc {
223					return nil, invalidProposal("proposal %s: delegation cycle involving %q", in.ID, chain[pos])
224				}
225				if head, resolved := headOf[next]; resolved {
226					cur = head
227					chain = append(chain, cur)
228					onChain[cur] = len(chain) - 1
229					break
230				}
231				chain = append(chain, next)
232				onChain[next] = len(chain) - 1
233				cur = next
234			}
235			head := cur
236			// 链上每个成员的路径都是自身后缀到 head。
237			for i := 0; i < len(chain); i++ {
238				member := chain[i]
239				if _, ok := headOf[member]; !ok {
240					path := append([]string(nil), chain[i:]...)
241					pathOf[member] = path
242					headOf[member] = head
243				}
244			}
245		}
246	
247		// 归集每个最终代表名下的全部原始权重；子集和必然不超过总权重。
248		groupW := make(map[string]int64)
249		for _, id := range order {
250			head := headOf[id]
251			sum, ok := addInt64(groupW[head], weights[id])
252			if !ok {
253				return nil, invalidProposal("proposal %s: delegated weight for %q overflows int64", in.ID, head)
254			}
255			groupW[head] = sum
256		}
257	
258		return &proposalSpec{
259			members:  append([]VoteMember(nil), in.Members...),
260			weights:  weights,
261			delegate: delegate,
262			pathOf:   pathOf,
263			headOf:   headOf,
264			groupW:   groupW,
265			total:    total,
266		}, nil
267	}
268	
269	func invalidProposal(format string, args ...any) error {
270		return fmt.Errorf("%w: %s", ErrInvalidProposal, fmt.Sprintf(format, args...))
271	}
272	
273	// proposalsEqual 判断重试内容是否与已存提案逐项相同。
274	// 成员与委托的输入次序不影响比较；动作文本与顺序必须一致。
275	func proposalsEqual(stored *storedVoteProposal, in *CreateVoteInput, spec *proposalSpec) bool {
276		if stored.Quorum != in.Quorum || stored.StartAt != in.StartAt ||
277			stored.Deadline != in.Deadline || stored.TimelockEnd != in.TimelockEnd {
278			return false
279		}
280		if !sameActions(stored.Actions, in.Actions) {
281			return false
282		}
283		if len(stored.Members) != len(in.Members) {
284			return false
285		}
286		for _, m := range stored.Members {
287			if w, ok := spec.weights[m.ID]; !ok || w != m.Weight {
288				return false
289			}
290		}
291		if len(stored.Delegations) != len(in.Delegations) {
292			return false
293		}
294		for _, d := range stored.Delegations {
295			to, ok := spec.delegate[d.From]
296			if !ok || to != d.To {
297				return false
298			}
299		}
300		return true
301	}
302	
303	// ---- 存储操作 ----
304	
305	// CreateVoteProposal 创建一项投票提案。
306	// 同编号且全部内容相同的重试返回已存在提案（existed=true）且不改变任何状态；
307	// 同编号内容不同（或编号已被 register 来源占用）返回 ErrProposalConflict。
308	// 非法条件整项拒绝，不落盘任何部分变化。
309	func (s *Store) CreateVoteProposal(in *CreateVoteInput) (view *VoteProposalView, existed bool, err error) {
310		spec, err := validateProposalInput(in)
311		if err != nil {
312			return nil, false, err
313		}
314		commit, err := s.begin()
315		if err != nil {
316			return nil, false, err
317		}
318		defer commit()
319	
320		state, err := s.loadLocked()
321		if err != nil {
322			return nil, false, err
323		}
324		if existing, ok := state.VoteProposals[in.ID]; ok {
325			if !proposalsEqual(existing, in, spec) {
326				return nil, false, fmt.Errorf("%w: voting proposal %s", ErrProposalConflict, in.ID)
327			}
328			v := voteProposalView(existing)
329			return v, true, nil
330		}
331		if _, ok := state.Proposals[in.ID]; ok {
332			// register 不能覆盖投票提案；反向同样拒绝，两种来源共用编号。
333			return nil, false, fmt.Errorf("%w: proposal id %s already registered", ErrProposalConflict, in.ID)
334		}
335	
336		stored := &storedVoteProposal{
337			ID:          in.ID,
338			State:       "voting",
339			Members:     make([]storedMember, 0, len(in.Members)),
340			Delegations: make([]storedDelegation, 0, len(in.Delegations)),
341			Quorum:      in.Quorum,
342			StartAt:     in.StartAt,
343			Deadline:    in.Deadline,
344			TimelockEnd: in.TimelockEnd,
345			Actions:     copyActions(in.Actions),
346			Ballots:     []storedBallot{},
347		}
348		for _, m := range in.Members {
349			stored.Members = append(stored.Members, storedMember{ID: m.ID, Weight: m.Weight})
350		}
351		for _, d := range in.Delegations {
352			stored.Delegations = append(stored.Delegations, storedDelegation{From: d.From, To: d.To})
353		}
354		state.VoteProposals[in.ID] = stored
355		if err := s.commitLocked(state); err != nil {
356			return nil, false, err
357		}
358		return voteProposalView(stored), false, nil
359	}
360	
361	func voteReject(reason string) error {
362		return fmt.Errorf("%w: %s", ErrVoteRejected, reason)
363	}
364	
365	func tallyReject(reason string) error {
366		return fmt.Errorf("%w: %s", ErrTallyRejected, reason)
367	}
368	
369	// CastVote 在一项投票提案上投票。调用方通过 now 提供当前时间。
370	// 只有最终代表本人可投赞成/反对票，每位代表一张票，票重为归集到其名下的
371	// 全部原始权重。相同选择的重试始终返回首次记录；改投报冲突。
372	// 首次投票只接受 start <= now < deadline；计票之后拒绝一切新票。
373	func (s *Store) CastVote(id, voter string, support bool, now int64) (*BallotView, error) {
374		if voter == "" {
375			return nil, voteReject("voter id must not be empty")
376		}
377		commit, err := s.begin()
378		if err != nil {
379			return nil, err
380		}
381		defer commit()
382	
383		state, err := s.loadLocked()
384		if err != nil {
385			return nil, err
386		}
387		p, ok := state.VoteProposals[id]
388		if !ok {
389			return nil, fmt.Errorf("%w: %s", ErrProposalNotFound, id)
390		}
391		spec, verr := specOf(p)
392		if verr != nil {
393			return nil, verr // 正常路径不会发生：打开与提交前均已严格校验
394		}
395		if _, member := spec.weights[voter]; !member {
396			return nil, voteReject(fmt.Sprintf("voter %q is not on the member roster of %s", voter, id))
397		}
398		if spec.headOf[voter] != voter {
399			return nil, voteReject(fmt.Sprintf("voter %q has delegated the vote to %q and may not vote directly", voter, spec.headOf[voter]))
400		}
401		// 已投过票：相同选择的重试始终返回首次记录（与时间窗口、是否已计票无关）；
402		// 改投另一选择报冲突，绝不静默覆盖。
403		for i := range p.Ballots {
404			if p.Ballots[i].Representative == voter {
405				if p.Ballots[i].Support != support {
406					return nil, fmt.Errorf("%w: representative %q already voted %s for %s; changing the vote is not allowed",
407						ErrProposalConflict, voter, voteChoice(p.Ballots[i].Support), id)
408				}
409				b := p.Ballots[i]
410				return &BallotView{Representative: b.Representative, Weight: b.Weight, Support: b.Support, VotedAt: b.VotedAt}, nil
411			}
412		}
413		if p.Tally != nil {
414			return nil, voteReject(fmt.Sprintf("proposal %s has already been tallied; voting is closed", id))
415		}
416		if now < p.StartAt || now >= p.Deadline {
417			return nil, voteReject(fmt.Sprintf("proposal %s is not open for voting at now=%d (start=%d deadline=%d)", id, now, p.StartAt, p.Deadline))
418		}
419	
420		p.Ballots = append(p.Ballots, storedBallot{
421			Representative: voter,
422			Weight:         spec.groupW[voter],
423			Support:        support,
424			VotedAt:        now,
425		})
426		if err := s.commitLocked(state); err != nil {
427			return nil, err
428		}
429		return &BallotView{Representative: voter, Weight: spec.groupW[voter], Support: support, VotedAt: now}, nil
430	}
431	
432	func voteChoice(support bool) string {
433		if support {
434			return "for"
435		}
436		return "against"
437	}
438	
439	// TallyVote 在截止时刻或之后进行首次计票：赞成与反对权重之和达到法定人数，
440	// 且赞成严格多于反对才通过。未投权重不计入参与量。
441	// 计票只确定状态，不转账；再次计票始终返回首次结论。
442	func (s *Store) TallyVote(id string, now int64) (*TallyResultView, error) {
443		commit, err := s.begin()
444		if err != nil {
445			return nil, err
446		}
447		defer commit()
448	
449		state, err := s.loadLocked()
450		if err != nil {
451			return nil, err
452		}
453		p, ok := state.VoteProposals[id]
454		if !ok {
455			return nil, fmt.Errorf("%w: %s", ErrProposalNotFound, id)
456		}
457		if p.Tally != nil {
458			return storedTallyResult(p), nil
459		}
460		if now < p.Deadline {
461			return nil, tallyReject(fmt.Sprintf("voting for %s is still open: now=%d deadline=%d", id, now, p.Deadline))
462		}
463	
464		spec, verr := specOf(p)
465		if verr != nil {
466			return nil, verr
467		}
468		var forW, againstW int64
469		seen := map[string]bool{}
470		for _, b := range p.Ballots {
471			if seen[b.Representative] {
472				return nil, fmt.Errorf("%w: proposal %s has duplicate stored ballot for %q", ErrStateCorrupt, id, b.Representative)
473			}
474			seen[b.Representative] = true
475			if b.Weight != spec.groupW[b.Representative] {
476				return nil, fmt.Errorf("%w: proposal %s ballot weight for %q (%d) does not match roster delegation (%d)",
477					ErrStateCorrupt, id, b.Representative, b.Weight, spec.groupW[b.Representative])
478			}
479			if b.Support {
480				sum, ok := addInt64(forW, b.Weight)
481				if !ok {
482					return nil, fmt.Errorf("%w: proposal %s vote weights overflow int64", ErrStateCorrupt, id)
483				}
484				forW = sum
485			} else {
486				sum, ok := addInt64(againstW, b.Weight)
487				if !ok {
488					return nil, fmt.Errorf("%w: proposal %s vote weights overflow int64", ErrStateCorrupt, id)
489				}
490				againstW = sum
491			}
492		}
493	
494		turnout, _ := addInt64(forW, againstW) // 不超过总权重
495		passed := turnout >= p.Quorum && forW > againstW
496		p.Tally = &storedTally{ForWeight: forW, AgainstWeight: againstW, TalliedAt: now}
497		if passed {
498			p.State = "passed"
499		} else {
500			p.State = "rejected"
501		}
502		if err := s.commitLocked(state); err != nil {
503			return nil, err
504		}
505		return storedTallyResult(p), nil
506	}
507	
508	// storedTallyResult 从已存储提案重建首次计票结论；尚未计票时返回 nil。
509	// Passed 按票数与法定人数重算：提案后续执行（executed）不改变首次结论。
510	func storedTallyResult(p *storedVoteProposal) *TallyResultView {
511		if p.Tally == nil {
512			return nil
513		}
514		turnout := p.Tally.ForWeight + p.Tally.AgainstWeight
515		return &TallyResultView{
516			ForWeight:     p.Tally.ForWeight,
517			AgainstWeight: p.Tally.AgainstWeight,
518			Turnout:       turnout,
519			Quorum:        p.Quorum,
520			Passed:        p.Tally.ForWeight > p.Tally.AgainstWeight && turnout >= p.Quorum,
521			TalliedAt:     p.Tally.TalliedAt,
522		}
523	}
524	
525	// VoteProposal 按编号查询一项投票提案；不存在时 ok 为 false。
526	func (s *Store) VoteProposal(id string) (*VoteProposalView, bool, error) {
527		state, err := s.readState()
528		if err != nil {
529			return nil, false, err
530		}
531		p, ok := state.VoteProposals[id]
532		if !ok {
533			return nil, false, nil
534		}
535		return voteProposalView(p), true, nil
536	}
537	
538	// VoteProposals 返回全部投票提案，按编号排序。
539	func (s *Store) VoteProposals() ([]*VoteProposalView, error) {
540		state, err := s.readState()
541		if err != nil {
542			return nil, err
543		}
544		out := make([]*VoteProposalView, 0, len(state.VoteProposals))
545		for _, p := range state.VoteProposals {
546			out = append(out, voteProposalView(p))
547		}
548		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
549		return out, nil
550	}
551	
552	func voteProposalView(p *storedVoteProposal) *VoteProposalView {
553		spec, err := specOf(p)
554		if err != nil {
555			// 调用方持有的状态均经过 validateState；损坏文件根本无法打开。
556			panic("govflow: building view of corrupt proposal: " + err.Error())
557		}
558		members := make([]MemberView, 0, len(p.Members))
559		for _, m := range p.Members { // 保持成员提交顺序
560			mv := MemberView{
561				ID:       m.ID,
562				Weight:   m.Weight,
563				Path:     append([]string(nil), spec.pathOf[m.ID]...),
564				Delegate: spec.headOf[m.ID],
565			}
566			if to, ok := spec.delegate[m.ID]; ok {
567				mv.Direct = to
568			}
569			members = append(members, mv)
570		}
571		ballots := make([]BallotView, 0, len(p.Ballots))
572		for _, b := range p.Ballots { // 保持首次投票先后顺序
573			ballots = append(ballots, BallotView{
574				Representative: b.Representative,
575				Weight:         b.Weight,
576				Support:        b.Support,
577				VotedAt:        b.VotedAt,
578			})
579		}
580		v := &VoteProposalView{
581			ID:          p.ID,
582			Source:      "vote",
583			State:       p.State,
584			Quorum:      p.Quorum,
585			StartAt:     p.StartAt,
586			Deadline:    p.Deadline,
587			TimelockEnd: p.TimelockEnd,
588			Actions:     copyActions(p.Actions),
589			TotalWeight: spec.total,
590			Members:     members,
591			Ballots:     ballots,
592		}
593		if p.Tally != nil {
594			v.Tally = storedTallyResult(p)
595		}
596		return v
597	}
598	
599	// specOf 从已存储提案重建校验派生物（委托路径、代表归集权重）。
600	func specOf(p *storedVoteProposal) (*proposalSpec, error) {
601		in := &CreateVoteInput{
602			ID:          p.ID,
603			Quorum:      p.Quorum,
604			StartAt:     p.StartAt,
605			Deadline:    p.Deadline,
606			TimelockEnd: p.TimelockEnd,
607			Actions:     p.Actions,
608		}
609		in.Members = make([]VoteMember, len(p.Members))
610		for i, m := range p.Members {
611			in.Members[i] = VoteMember{ID: m.ID, Weight: m.Weight}
612		}
613		in.Delegations = make([]Delegation, len(p.Delegations))
614		for i, d := range p.Delegations {
615			in.Delegations[i] = Delegation{From: d.From, To: d.To}
616		}
617		return validateProposalInput(in)
618	}
619	
620	// validateVoteProposals 在打开状态文件时严格校验全部投票提案：
621	// 编号与 register 来源不冲突；状态机与计票结论一致；票重/代表与名单及委托明细一致；
622	// 首次投票时间落在窗口内；首次计票不早于截止且结论可由明细重放。
623	func validateVoteProposals(state *storedState) error {
624		for key, p := range state.VoteProposals {
625			if p == nil {
626				return fmt.Errorf("voting proposal %q is empty", key)
627			}
628			if p.ID != key || p.ID == "" {
629				return fmt.Errorf("voting proposal key %q does not match id %q", key, p.ID)
630			}
631			if _, collide := state.Proposals[p.ID]; collide {
632				return fmt.Errorf("proposal id %q exists in both proposal sources", p.ID)
633			}
634			switch p.State {
635			case "voting", "passed", "rejected", "executed":
636			default:
637				return fmt.Errorf("voting proposal %q has unknown state %q", p.ID, p.State)
638			}
639			spec, err := specOf(p)
640			if err != nil {
641				return err
642			}
643	
644			// 票据明细：代表必须是最终代表，票重必须等于名单与委托归集出的权重。
645			seenReps := map[string]bool{}
646			var ballotFor, ballotAgainst int64
647			for i, b := range p.Ballots {
648				if b.Representative == "" {
649					return fmt.Errorf("voting proposal %q ballot %d has empty representative", p.ID, i)
650				}
651				if spec.headOf[b.Representative] != b.Representative {
652					return fmt.Errorf("voting proposal %q ballot %d: %q is not a final representative", p.ID, i, b.Representative)
653				}
654				if seenReps[b.Representative] {
655					return fmt.Errorf("voting proposal %q has duplicate ballot for representative %q", p.ID, b.Representative)
656				}
657				seenReps[b.Representative] = true
658				if b.Weight != spec.groupW[b.Representative] {
659					return fmt.Errorf("voting proposal %q ballot weight for %q is %d, roster/delegations yield %d",
660						p.ID, b.Representative, b.Weight, spec.groupW[b.Representative])
661				}
662				if b.VotedAt < p.StartAt || b.VotedAt >= p.Deadline {
663					return fmt.Errorf("voting proposal %q ballot by %q cast at %d outside window [%d,%d)",
664						p.ID, b.Representative, b.VotedAt, p.StartAt, p.Deadline)
665				}
666				if b.Support {
667					sum, ok := addInt64(ballotFor, b.Weight)
668					if !ok {
669						return fmt.Errorf("voting proposal %q ballot weights overflow int64", p.ID)
670					}
671					ballotFor = sum
672				} else {
673					sum, ok := addInt64(ballotAgainst, b.Weight)
674					if !ok {
675						return fmt.Errorf("voting proposal %q ballot weights overflow int64", p.ID)
676					}
677					ballotAgainst = sum
678				}
679			}
680	
681			switch {
682			case p.Tally == nil:
683				if p.State != "voting" {
684					return fmt.Errorf("voting proposal %q is %s but has no tally", p.ID, p.State)
685				}
686			default:
687				if p.State == "voting" {
688					return fmt.Errorf("voting proposal %q has a tally but is still in voting state", p.ID)
689				}
690				if p.Tally.TalliedAt < p.Deadline {
691					return fmt.Errorf("voting proposal %q tallied at %d before deadline %d", p.ID, p.Tally.TalliedAt, p.Deadline)
692				}
693				if p.Tally.ForWeight != ballotFor || p.Tally.AgainstWeight != ballotAgainst {
694					return fmt.Errorf("voting proposal %q tally weights for=%d/against=%d do not replay ballots for=%d/against=%d",
695						p.ID, p.Tally.ForWeight, p.Tally.AgainstWeight, ballotFor, ballotAgainst)
696				}
697				turnout := ballotFor + ballotAgainst
698				passedNow := turnout >= p.Quorum && ballotFor > ballotAgainst
699				if passedNow != (p.State == "passed" || p.State == "executed") {
700					return fmt.Errorf("voting proposal %q state %s does not match quorum/majority replay", p.ID, p.State)
701				}
702			}
703		}
704		return nil
705	}
