243	// delegationList 收集重复的 --delegate FROM:TO 参数，保持提交顺序。
244	type delegationList []govflow.Delegation
245	
246	func (d *delegationList) String() string { return fmt.Sprint([]govflow.Delegation(*d)) }
247	func (d *delegationList) Set(v string) error {
248		from, to, ok := strings.Cut(v, ":")
249		if !ok || from == "" || to == "" {
250			return fmt.Errorf("malformed delegation %q, expected FROM:TO", v)
251		}
252		*d = append(*d, govflow.Delegation{From: from, To: to})
253		return nil
254	}
