595	func printVoteProposalText(v *govflow.VoteProposalView) {
596		fmt.Printf("proposal %s source=vote state=%s quorum=%d voting=[%d,%d) timelock_end=%d actions=%d total_weight=%d\n",
597			v.ID, v.State, v.Quorum, v.StartAt, v.Deadline, v.TimelockEnd, len(v.Actions), v.TotalWeight)
598		for _, m := range v.Members {
599			chain := strings.Join(m.Path, "->")
600			if len(m.Path) == 1 {
601				fmt.Printf("  member %s weight=%d representative=self\n", m.ID, m.Weight)
602			} else {
603				fmt.Printf("  member %s weight=%d path=%s\n", m.ID, m.Weight, chain)
604			}
605		}
606		for i, action := range v.Actions {
607			fmt.Printf("  action %d: %s\n", i, action)
608		}
609		for _, b := range v.Ballots {
610			fmt.Printf("  ballot representative=%s choice=%s weight=%d voted_at=%d\n",
611				b.Representative, choiceWord(b.Support), b.Weight, b.VotedAt)
612		}
613		if v.Tally != nil {
614			verdict := "rejected"
615			if v.Tally.Passed {
616				verdict = "passed"
617			}
618			fmt.Printf("  tally for=%d against=%d turnout=%d => %s tallied_at=%d\n",
619				v.Tally.ForWeight, v.Tally.AgainstWeight, v.Tally.Turnout, verdict, v.Tally.TalliedAt)
620		}
621	}
622	
623	func printReceiptText(r *govflow.Receipt, header bool) {
624		if header {
625			fmt.Printf("receipt proposal=%s order=%d executed_at=%d actions=%d\n", r.ProposalID, r.Order, r.ExecutedAt, len(r.Actions))
626		} else {
627			fmt.Printf("executed proposal %s at %d (%d action(s)); receipt order %d\n", r.ProposalID, r.ExecutedAt, len(r.Actions), r.Order)
628		}
629		for _, ar := range r.Actions {
630			fmt.Printf("  action %d: %s\n", ar.Index, ar.Action)
631			fmt.Printf("    treasury:  %d -> %d\n", ar.Treasury.Before, ar.Treasury.After)
632			fmt.Printf("    %s: %d -> %d\n", ar.Recipient.Account, ar.Recipient.Before, ar.Recipient.After)
633		}
634	}
635	
636	func runDemo() {
637		proposal := govflow.Proposal{ID: "gip-7", Title: "fund the audit workstream", State: "voting", Quorum: 1000,
638			TimelockEnd: 5000, Actions: []string{"transfer:audits:25000"}}
639		if err := govflow.Vote(&proposal, 700, true); err != nil {
640			fmt.Println("vote refused:", err)
641		}
642		if err := govflow.Vote(&proposal, 200, false); err != nil {
643			fmt.Println("vote refused:", err)
644		}
645		next := govflow.Tally(&proposal)
646		fmt.Printf("proposal=%s for=%d against=%d quorum=%d next=%s\n", proposal.ID, proposal.ForVotes, proposal.AgainstVotes, proposal.Quorum, next)
647		proposal.State = next
648		proposal.TimelockEnd = 400
649		fmt.Println("executable now:", govflow.Executable([]govflow.Proposal{proposal}, 1000))
650	}
