162		store, _ := openTempStore(t, 1000)
163		defer store.Close()
164		in := &CreateVoteInput{
165			ID:      "gip-chain",
166			Members: []VoteMember{{ID: "a", Weight: 1}, {ID: "b", Weight: 2}, {ID: "c", Weight: 4}, {ID: "d", Weight: 8}, {ID: "e", Weight: 16}},
167			// a -> b -> c(停止)；d -> c；e 自代。
168			Delegations: []Delegation{{From: "a", To: "b"}, {From: "b", To: "c"}, {From: "d", To: "c"}},
169			Quorum:      15, StartAt: 0, Deadline: 10, TimelockEnd: 10,
170		}
171		view := mustCreateVote(t, store, in)
172		wantPath := map[string][]string{
173			"a": {"a", "b", "c"},
174			"b": {"b", "c"},
175			"c": {"c"},
176			"d": {"d", "c"},
177			"e": {"e"},
178		}
179		wantHead := map[string]string{"a": "c", "b": "c", "c": "c", "d": "c", "e": "e"}
180		for _, m := range view.Members {
181			if !equalStrings(m.Path, wantPath[m.ID]) {
182				t.Errorf("member %s path=%v want %v", m.ID, m.Path, wantPath[m.ID])
183			}
184			if m.Delegate != wantHead[m.ID] {
185				t.Errorf("member %s head=%s want %s", m.ID, m.Delegate, wantHead[m.ID])
186			}
187		}
188	
189		// 已委托出去的成员不能直接投票；最终代表 c 归集 1+2+4+8=15。
190		if _, err := store.CastVote("gip-chain", "a", true, 5); !errors.Is(err, ErrVoteRejected) {
191			t.Fatalf("delegated member voted: %v", err)
192		}
193		if _, err := store.CastVote("gip-chain", "ghost", true, 5); !errors.Is(err, ErrVoteRejected) {
194			t.Fatalf("non-member voted: %v", err)
195		}
196		b, err := store.CastVote("gip-chain", "c", true, 5)
197		if err != nil {
198			t.Fatalf("representative vote: %v", err)
199		}
200		if b.Weight != 15 {
201			t.Fatalf("group weight=%d, want 15", b.Weight)
202		}
203		b2, err := store.CastVote("gip-chain", "c", true, 9) // 窗口外重试
204		if err != nil || b2.VotedAt != 5 || b2.Weight != 15 {
205			t.Fatalf("identical retry: %+v err=%v", b2, err)
206		}
207		if _, err := store.CastVote("gip-chain", "c", false, 5); !errors.Is(err, ErrProposalConflict) {
208			t.Fatalf("changing vote err=%v", err)
209		}
210	}
