422	func TestConcurrentVotingAndTally(t *testing.T) {
423		store, _ := openTempStore(t, 1000)
424		defer store.Close()
425		in := baseVoteInput("gip-conc")
426		mustCreateVote(t, store, in)
427	
428		// 两名代表在同一时刻反复投同一选择；只能各成功一次且票据不重复。
429		var wg sync.WaitGroup
430		errs := make(chan error, 64)
431		start := make(chan struct{})
432		vote := func(voter string, support bool, now int64) {
433			defer wg.Done()
434			<-start
435			if _, err := store.CastVote("gip-conc", voter, support, int64(now)); err != nil {
436				errs <- err
437			}
438		}
439		for i := 0; i < 16; i++ {
440			wg.Add(2)
441			go vote("alice", true, 150)
442			go vote("dave", false, 150)
443		}
444		close(start)
445		wg.Wait()
446		close(errs)
447		for err := range errs {
448			t.Errorf("concurrent identical vote: %v", err)
449		}
450		v, _, _ := store.VoteProposal("gip-conc")
451		if len(v.Ballots) != 2 {
452			t.Fatalf("ballot count=%d, want 2", len(v.Ballots))
453		}
454	
455		// 计票与投票并发：只有先于计票成功的票进入结论；二者由同一把锁串行。
456		in2 := baseVoteInput("gip-conc2")
457		in2.Quorum = 1000
458		mustCreateVote(t, store, in2)
459		var wg2 sync.WaitGroup
460		start2 := make(chan struct{})
461		wg2.Add(1)
462		go func() { // 迟到的票：可能在计票前或后
463			defer wg2.Done()
464			<-start2
465			_, _ = store.CastVote("gip-conc2", "dave", false, 150)
466		}()
467		wg2.Add(1)
468		go func() {
469			defer wg2.Done()
470			<-start2
471			_, _ = store.TallyVote("gip-conc2", 200)
472		}()
473		close(start2)
474		wg2.Wait()
475		v2, _, _ := store.VoteProposal("gip-conc2")
476		if v2.Tally == nil {
477			t.Fatal("proposal not tallied")
478		}
479		// 结论必须能由已保存票据重放（打开/提交时的严格校验兜底；这里再显式断言）。
480		var forW, againstW int64
481		for _, b := range v2.Ballots {
482			if b.Support {
483				forW += b.Weight
484			} else {
485				againstW += b.Weight
486			}
487		}
488		if forW != v2.Tally.ForWeight || againstW != v2.Tally.AgainstWeight {
489			t.Fatalf("tally %+v inconsistent with ballots for=%d against=%d", v2.Tally, forW, againstW)
490		}
491	}
