579	}
580	
581	func TestTamperedVoteStateRejected(t *testing.T) {
582		dir := t.TempDir()
583		path := filepath.Join(dir, "treasury.json")
584		store, err := InitTreasury(path, 1000)
585		if err != nil {
586			t.Fatal(err)
587		}
588		in := baseVoteInput("gip-tamper")
589		mustCreateVote(t, store, in)
590		if _, err := store.CastVote("gip-tamper", "alice", true, 150); err != nil {
591			t.Fatal(err)
592		}
593		if _, err := store.TallyVote("gip-tamper", 200); err != nil {
594			t.Fatal(err)
595		}
596		store.Close()
597	
598		good, err := os.ReadFile(path)
599		if err != nil {
600			t.Fatal(err)
601		}
602		// 用结构化改写构造损坏变体，避免依赖具体缩进。
603		mutate := func(fn func(p map[string]any)) []byte {
604			var clone map[string]any
605			if err := json.Unmarshal(good, &clone); err != nil {
606				t.Fatal(err)
607			}
608			p := clone["vote_proposals"].(map[string]any)["gip-tamper"].(map[string]any)
609			fn(p)
610			raw, err := json.MarshalIndent(clone, "", "  ")
611			if err != nil {
612				t.Fatal(err)
613			}
614			return append(raw, '\n')
615		}
616		cases := map[string][]byte{
617			"ballot weight mismatch": mutate(func(p map[string]any) {
618				p["ballots"].([]any)[0].(map[string]any)["weight"] = 601
619			}),
620			"ballot from non-head": mutate(func(p map[string]any) {
621				p["ballots"].([]any)[0].(map[string]any)["representative"] = "bob"
622			}),
623			"duplicate ballot rep": mutate(func(p map[string]any) {
624				extra := map[string]any{"representative": "alice", "weight": 600, "support": true, "voted_at": 151}
625				p["ballots"] = append(p["ballots"].([]any), extra)
626			}),
627			"tally before deadline": mutate(func(p map[string]any) {
628				p["tally"].(map[string]any)["tallied_at"] = 199
629			}),
630			"tally disagrees with ballots": mutate(func(p map[string]any) {
631				p["tally"].(map[string]any)["for_weight"] = 601
632			}),
633			"unknown vote state": mutate(func(p map[string]any) {
634				p["state"] = "approved"
635			}),
636			"quorum out of range": mutate(func(p map[string]any) {
637				p["quorum"] = 1001
638			}),
639		}
640		// id collision：在 register 来源表里注入同一编号。
641		collision := mutate(func(p map[string]any) {})
642		var cd map[string]any
643		if err := json.Unmarshal(collision, &cd); err != nil {
644			t.Fatal(err)
645		}
646		cd["proposals"] = map[string]any{"gip-tamper": map[string]any{
647			"id": "gip-tamper", "state": "passed", "timelock_end": 300,
648			"actions": []any{"transfer:audits:100"},
649		}}
650		if raw, err := json.MarshalIndent(cd, "", "  "); err != nil {
651			t.Fatal(err)
652		} else {
653			cases["id collision"] = append(raw, '\n')
654		}
655		for name, raw := range cases {
656			t.Run(name, func(t *testing.T) {
657				bad := filepath.Join(dir, "bad-"+strings.ReplaceAll(name, " ", "-")+".json")
658				if err := os.WriteFile(bad, raw, 0o600); err != nil {
659					t.Fatal(err)
660				}
661				s, err := Open(bad)
662				if !errors.Is(err, ErrStateCorrupt) {
663					if s != nil {
664						s.Close()
665					}
666					t.Fatalf("Open err=%v, want ErrStateCorrupt", err)
667				}
668				if got, rerr := os.ReadFile(bad); rerr != nil || string(got) != string(raw) {
669					t.Fatalf("corrupt file was modified")
670				}
671			})
672		}
673	}
